insert into public.products (id, year, make, model, trim, category, condition, price, msrp, usage_value, usage_unit, location_id, stock_number, color, description, specifications, features, images, featured, special) values ('yz-mt09-2025', 2025, 'Yamaha', 'MT-09', 'SP', 'motorcycles', 'New', 11799, 12499, NULL, NULL, 'burlington', 'RM-24901', 'Matte Raven Black', 'The MT-09 SP takes the 890cc CP3 triple and wraps it in fully adjustable KYB front forks and an Öhlins rear shock. Cruise control, a six-axis IMU and three-mode traction control make it as usable on the Turnpike as it is aggressive through the Redland backroads.', '[{"label":"Engine","value":"890cc liquid-cooled DOHC inline 3-cylinder"},{"label":"Bore x Stroke","value":"78.0mm x 62.0mm"},{"label":"Transmission","value":"6-speed w/ quickshifter"},{"label":"Front Suspension","value":"KYB 41mm inverted fork, fully adjustable"},{"label":"Rear Suspension","value":"Öhlins shock, fully adjustable"},{"label":"Front Brakes","value":"Dual 298mm discs, radial-mount 4-piston"},{"label":"Seat Height","value":"32.5 in"},{"label":"Fuel Capacity","value":"3.7 gal"},{"label":"Curb Weight","value":"417 lb"}]'::jsonb, ARRAY['Six-axis IMU with lean-sensitive rider aids', 'Up/down quickshifter', 'Cruise control', '5-inch full-colour TFT display', 'Three ride modes plus two custom modes', 'Öhlins rear suspension']::text[], ARRAY['/images/products/yz-mt09-2025-1.webp', '/images/products/yz-mt09-2025-2.webp', '/images/products/yz-mt09-2025-3.webp']::text[], true, true)
