insert into public.products (id, year, make, model, trim, category, condition, price, msrp, usage_value, usage_unit, location_id, stock_number, color, description, specifications, features, images, featured, special) values ('seadoo-rxtx-2025', 2025, 'Sea-Doo', 'RXT-X 325', NULL, 'watercraft', 'New', 20399, 21799, NULL, NULL, 'burlington', 'RM-24488', 'Manta Green', '325 supercharged horsepower on the ST3 hull. The RXT-X is the offshore weapon of the Sea-Doo line — it settles into a chop that punishes lighter skis and still turns like a runabout when the bay goes flat.', '[{"label":"Engine","value":"1630 ACE 325 supercharged"},{"label":"Horsepower","value":"325 hp"},{"label":"Hull","value":"ST3"},{"label":"Length","value":"146.4 in"},{"label":"Fuel Capacity","value":"18.5 gal"},{"label":"Storage","value":"40.3 gal"},{"label":"Rider Capacity","value":"3"},{"label":"Dry Weight","value":"858 lb"}]'::jsonb, ARRAY['Ergolock R seat with adjustable handlebars', 'iBR intelligent brake and reverse', '7.8-inch wide colour display', 'Launch control and ski mode', 'Adjustable trim (VTS)', 'BRP Audio premium system ready']::text[], ARRAY['/images/products/seadoo-rxtx-2025-1.webp', '/images/products/seadoo-rxtx-2025-2.webp', '/images/products/seadoo-rxtx-2025-3.webp']::text[], true, true)
